  border: 2px solid var(--forest);
}
.btn-dark:hover { background: var(--gray-900); border-color: var(--gray-900); }
.btn-sm { padding: 8px 20px; font-size: 0.875rem; }
.btn-lg { padding: 16px 40px; font-size: 1.0625rem; }

/* ── Layout ── */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.container-sm { max-width: 960px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }

/* ── Header / Nav ── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-100);
  box-shadow: var(--shadow-sm);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  gap: 32px;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'DM Serif Display', serif;
  font-size: 1.375rem;
  color: var(--green);
  flex-shrink: 0;
}
.logo-icon {
  width: 44px;
  height: 44px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.25rem;
  font-weight: 700;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  justify-content: center;
}
.nav-links a {
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-links a:hover { background: var(--green-light); color: var(--green); }
.nav-links a.active { color: var(--green); font-weight: 600; }
.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}
.nav-actions a { font-size: 0.9375rem; font-weight: 500; color: var(--gray-700); padding: 8px 16px; transition: color var(--transition); }
.nav-actions a:hover { color: var(--green); }
.nav-mobile-toggle {
  display: none;
  padding: 8px;
  border-radius: var(--radius-sm);
  color: var(--gray-700);
  font-size: 1.5rem;
}

/* ── Cookie Banner ── */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--forest);
  color: var(--white);
  z-index: 200;
  padding: 20px 0;
  border-top: 3px solid var(--green);
}
.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.cookie-text h4 { font-family: 'DM Serif Display', serif; font-size: 1.1rem; margin-bottom: 4px; }
.cookie-text p { font-size: 0.875rem; color: rgba(255,255,255,0.8); }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ── Hero ── */
.hero {
  background: linear-gradient(135deg, var(--forest) 0%, #1a3317 50%, #0d2b0d 100%);
  color: var(--white);
  min-height: 580px;
  display: flex;
  align-items: center;
  overflow: hidden;
  position: relative;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%2300824A' fill-opacity='0.05'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  padding: 80px 0;
  position: relative;
  z-index: 1;
}
.hero-content h1 { font-size: clamp(2.5rem, 5vw, 4rem); margin-bottom: 24px; color: var(--cream); }
.hero-content p { font-size: 1.125rem; color: rgba(255,255,255,0.85); margin-bottom: 36px; max-width: 440px; font-family: 'DM Sans', sans-serif; }
.hero-image {
  display: flex;
  justify-content: center;
  align-items: center;
}
.hero-img-placeholder {
  width: 420px;
  height: 380px;
  background: linear-gradient(145deg, rgba(243,206,161,0.2), rgba(0,130,74,0.3));
  border-radius: var(--radius-xl);
  border: 1px solid rgba(243,206,161,0.3);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}
.hero-img-placeholder .img-icon { font-size: 4rem; opacity: 0.6; }

/* ── Promo Cards ── */
.promo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}
.promo-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: transform var(--transition), box-shadow var(--transition);
}
.promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.promo-card-img {
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  font-weight: 700;
  color: rgba(255,255,255,0.4);
  position: relative;
}
.promo-card-body { padding: 28px; }
.promo-card-body h3 { font-size: 1.375rem; margin-bottom: 12px; }
.promo-card-body p { font-size: 0.9375rem; color: var(--gray-500); margin-bottom: 20px; line-height: 1.6; font-family: 'DM Sans', sans-serif; }

.card-citrus .promo-card-img { background: linear-gradient(135deg, #F97316, #FCD34D); }
.card-citrus .promo-card-body h3 { color: var(--brown); }

.card-afternoon .promo-card-img { background: linear-gradient(135deg, #7C3AED, #DB2777); }
.card-afternoon .promo-card-body h3 { color: var(--forest); }

.card-ai .promo-card-img { background: linear-gradient(135deg, #0EA5E9, #6366F1); }
.card-ai .promo-card-body h3 { color: var(--forest); }

/* ── Seasonal Highlights ── */
.seasonal-section { background: var(--cream-light); }
.seasonal-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.seasonal-panel {
  padding: 60px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 20px;
}
.seasonal-panel:first-child { background: linear-gradient(145deg, #FFF8F0, #FCEBD0); }
.seasonal-panel:last-child { background: linear-gradient(145deg, #E8F5EE, #C8E8D8); }
.seasonal-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  width: fit-content;
}
.tag-mango { background: rgba(249,115,22,0.15); color: #C2410C; }
.tag-spring { background: rgba(0,130,74,0.12); color: var(--green-dark); }
.seasonal-panel h2 { font-size: 1.75rem; color: var(--forest); }
.seasonal-panel p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.7; font-family: 'DM Sans', sans-serif; }

/* ── Nondairy Banner ── */
.nondairy-banner {
  background: var(--forest);
  color: var(--white);
  padding: 60px 0;
}
.nondairy-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}
.nondairy-inner h2 { font-size: 2.25rem; color: var(--cream); }
.nondairy-inner p { font-size: 1rem; color: rgba(255,255,255,0.8); margin-top: 8px; font-family: 'DM Sans', sans-serif; }

/* ── Footer ── */
.site-footer {
  background: var(--gray-900);
  color: var(--white);
  padding: 64px 0 32px;
}
.footer-top {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}
.footer-col h4 {
  font-family: 'DM Sans', sans-serif;
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400);
  margin-bottom: 16px;
  cursor: default;
}
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul li a {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--cream); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.footer-bottom p { font-size: 0.8125rem; color: var(--gray-400); }
.footer-bottom a { color: var(--gray-400); margin-left: 20px; font-size: 0.8125rem; }
.footer-bottom a:hover { color: var(--cream); }
.footer-social { display: flex; gap: 16px; }
.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  transition: background var(--transition);
}
.footer-social a:hover { background: var(--green); }
.footer-accordion-toggle { display: none; }

/* ── Section Headers ── */
.section-header { text-align: center; margin-bottom: 48px; }
.section-header h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); color: var(--forest); margin-bottom: 12px; }
.section-header p { font-size: 1.0625rem; color: var(--gray-500); max-width: 560px; margin: 0 auto; font-family: 'DM Sans', sans-serif; }
.section-eyebrow {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--green);
  margin-bottom: 8px;
}

/* ── Utility ── */
.divider { height: 1px; background: var(--gray-100); }
.star-icon { color: #F59E0B; }
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 12px;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
}
.badge-green { background: var(--green-light); color: var(--green-dark); }
.badge-gold { background: rgba(245,158,11,0.15); color: #92400E; }
.badge-reserve { background: rgba(99,102,241,0.12); color: #3730A3; }

/* ── Mobile Nav ── */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: var(--white);
  z-index: 150;
  padding: 24px;
  flex-direction: column;
  gap: 8px;
}
.mobile-menu.open { display: flex; }
.mobile-menu-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.mobile-menu a {
  display: block;
  padding: 16px 20px;
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
}
.mobile-menu a:hover { background: var(--green-light); color: var(--green); }

/* ── Breadcrumb ── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px 0;
  font-size: 0.875rem;
  color: var(--gray-400);
}
.breadcrumb a { color: var(--gray-500); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb span { color: var(--gray-700); font-weight: 500; }

/* ── Menu Page ── */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  padding: 40px 0 80px;
}
.menu-sidebar {
  position: sticky;
  top: 90px;
  align-self: start;
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  padding: 24px 0;
  border: 1px solid var(--gray-100);
  max-height: calc(100vh - 110px);
  overflow-y: auto;
}
.sidebar-group { margin-bottom: 8px; }
.sidebar-group-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  padding: 12px 20px 6px;
}
.sidebar-link {
  display: block;
  padding: 10px 20px;
  font-size: 0.9375rem;
  color: var(--gray-700);
  transition: all var(--transition);
  border-left: 3px solid transparent;
}
.sidebar-link:hover { background: var(--green-light); color: var(--green); border-left-color: var(--green); }
.sidebar-link.active { background: var(--green-light); color: var(--green); border-left-color: var(--green); font-weight: 600; }

.menu-content h2.category-title {
  font-size: 1.75rem;
  color: var(--forest);
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--green-light);
}
.menu-category-section { margin-bottom: 56px; }
.menu-items-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 20px; }
.menu-item-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}
.menu-item-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); border-color: var(--green-light); }
.menu-item-thumb {
  height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  background: var(--cream-light);
}
.menu-item-info { padding: 14px; }
.menu-item-info h4 { font-family: 'DM Sans', sans-serif; font-size: 0.9375rem; font-weight: 600; color: var(--gray-900); margin-bottom: 4px; }
.menu-item-info p { font-size: 0.8125rem; color: var(--gray-400); }

/* ── Rewards Page ── */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}
.rewards-hero h1 { font-size: clamp(2rem, 5vw, 3.5rem); color: var(--cream); margin-bottom: 16px; }
.rewards-hero p { font-size: 1.125rem; color: rgba(255,255,255,0.85); max-width: 540px; margin: 0 auto 32px; font-family: 'DM Sans', sans-serif; }
.rewards-actions { display: flex; gap: 16px; justify-content: center; }

.how-it-works { background: var(--cream-light); }
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.step-card {
  text-align: center;
  padding: 40px 28px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition);
}
.step-card:hover { transform: translateY(-4px); }
.step-number {
  width: 60px;
  height: 60px;
  background: var(--green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'DM Serif Display', serif;
  font-size: 1.5rem;
  color: var(--white);
  margin: 0 auto 20px;
}
.step-card h3 { font-size: 1.25rem; color: var(--forest); margin-bottom: 12px; }
.step-card p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.6; font-family: 'DM Sans', sans-serif; }

.tiers-section { }
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.tier-card {
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  border: 2px solid var(--gray-100);
  transition: all var(--transition);
}
.tier-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.tier-card.tier-green { border-color: var(--green-light); }
.tier-card.tier-gold { border-color: rgba(245,158,11,0.3); background: rgba(245,158,11,0.03); }
.tier-card.tier-reserve { border-color: rgba(99,102,241,0.3); background: rgba(99,102,241,0.03); }
.tier-header { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; }
.tier-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.tier-icon-green { background: var(--green-light); }
.tier-icon-gold { background: rgba(245,158,11,0.15); }
.tier-icon-reserve { background: rgba(99,102,241,0.12); }
.tier-name { font-size: 1.25rem; font-family: 'DM Serif Display', serif; }
.tier-threshold { font-size: 0.8125rem; color: var(--gray-400); margin-top: 2px; font-family: 'DM Sans', sans-serif; }
.tier-benefits { display: flex; flex-direction: column; gap: 10px; }
.tier-benefit {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.9375rem;
  color: var(--gray-600);
  font-family: 'DM Sans', sans-serif;
}
.tier-benefit::before { content: '✓'; color: var(--green); font-weight: 700; flex-shrink: 0; margin-top: 1px; }

/* ── Redemption Tabs ── */
.redemption-section { background: var(--cream-light); }
.redemption-tabs {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 40px;
}
.redemption-tab {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  border: 2px solid var(--gray-200);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-500);
  background: var(--white);
  transition: all var(--transition);
  display: flex;
  align-items: center;
  gap: 6px;
}
.redemption-tab:hover { border-color: var(--green); color: var(--green); }
.redemption-tab.active {
  background: var(--green);
  border-color: var(--green);
  color: var(--white);
  box-shadow: 0 4px 12px rgba(0,130,74,0.3);
}
.redemption-content {
  display: none;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-md);
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}
.redemption-content.active { display: flex; flex-direction: column; align-items: center; gap: 16px; }
.redemption-stars { font-size: 3rem; font-family: 'DM Serif Display', serif; color: var(--green); }
.redemption-value {
  display: inline-block;
  padding: 8px 24px;
  background: var(--green-light);
  color: var(--green-dark);
  border-radius: var(--radius-full);
  font-size: 1rem;
  font-weight: 700;
}
.redemption-desc { font-size: 1.125rem; color: var(--gray-700); font-family: 'DM Sans', sans-serif; }
.redemption-icon { font-size: 4rem; }

/* ── Partnerships ── */
.partnerships-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; max-width: 800px; margin: 0 auto; }
.partner-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  align-items: flex-start;
  gap: 20px;
  box-shadow: var(--shadow-sm);
}
.partner-logo {
  width: 60px;
  height: 60px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  flex-shrink: 0;
}
.partner-logo.delta { background: #1D4ED8; color: white; }
.partner-logo.marriott { background: #B91C1C; color: white; }
.partner-info h4 { font-size: 1.125rem; color: var(--forest); margin-bottom: 8px; }
.partner-info p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; font-family: 'DM Sans', sans-serif; }

/* ── App Download ── */
.app-section { background: var(--forest); color: var(--white); }
.app-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
.app-text h2 { font-size: 2rem; color: var(--cream); margin-bottom: 12px; }
.app-text p { font-size: 1rem; color: rgba(255,255,255,0.8); margin-bottom: 24px; font-family: 'DM Sans', sans-serif; }
.app-buttons { display: flex; gap: 16px; flex-wrap: wrap; }
.app-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 20px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-md);
  color: var(--white);
  font-size: 0.9375rem;
  transition: all var(--transition);
}
.app-btn:hover { background: rgba(255,255,255,0.2); }
.app-btn-icon { font-size: 1.75rem; }
.app-btn-text { display: flex; flex-direction: column; }
.app-btn-text small { font-size: 0.75rem; opacity: 0.7; }
.app-btn-text span { font-weight: 600; }
.app-phones {
  display: flex;
  gap: 16px;
  flex-shrink: 0;
}
.phone-mockup {
  width: 120px;
  height: 240px;
  background: rgba(255,255,255,0.1);
  border: 2px solid rgba(255,255,255,0.2);
  border-radius: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

/* ── Gift Cards ── */
.gift-hero { background: linear-gradient(135deg, #FFF8F0, #FCEBD0); padding: 64px 0; }
.gift-hero-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
.gift-hero h1 { font-size: 2.5rem; color: var(--forest); margin-bottom: 12px; }
.gift-hero p { font-size: 1rem; color: var(--gray-500); max-width: 440px; margin-bottom: 28px; font-family: 'DM Sans', sans-serif; }
.gift-hero-cards { display: flex; gap: 12px; }
.gift-card-mini {
  width: 100px;
  height: 65px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: white;
  font-weight: 700;
  box-shadow: var(--shadow-md);
}

.carousel-section { }
.carousel-title {
  font-size: 1.5rem;
  color: var(--forest);
  margin-bottom: 24px;
  font-family: 'DM Serif Display', serif;
}
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track { display: flex; gap: 20px; transition: transform 0.4s cubic-bezier(0.25,0.46,0.45,0.94); }
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  z-index: 10;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  color: var(--gray-700);
}
.carousel-btn:hover { border-color: var(--green); color: var(--green); box-shadow: var(--shadow-md); }
.carousel-btn-prev { left: -22px; }
.carousel-btn-next { right: -22px; }

.gift-card-item {
  flex: 0 0 220px;
  cursor: pointer;
  transition: transform var(--transition);
}
.gift-card-item:hover { transform: translateY(-4px); }
.gift-card-visual {
  height: 140px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  color: white;
  font-weight: 700;
  margin-bottom: 10px;
  box-shadow: var(--shadow-sm);
}
.gift-card-label { font-size: 0.875rem; font-weight: 500; color: var(--gray-700); text-align: center; }

.business-gifting {
  background: var(--forest);
  color: var(--white);
  padding: 64px 0;
}
.business-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
.business-text h2 { font-size: 2rem; color: var(--cream); margin-bottom: 12px; }
.business-text p { font-size: 1rem; color: rgba(255,255,255,0.8); max-width: 500px; margin-bottom: 24px; font-family: 'DM Sans', sans-serif; }
.business-badge {
  display: flex;
  gap: 12px;
  margin-top: 20px;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
}
.business-badge span { display: flex; align-items: center; gap: 4px; }

.egift-section { background: var(--cream-light); }
.egift-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.egift-text h2 { font-size: 1.75rem; color: var(--forest); margin-bottom: 16px; }
.egift-text p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.7; margin-bottom: 20px; font-family: 'DM Sans', sans-serif; }
.egift-features { display: flex; flex-direction: column; gap: 12px; }
.egift-feature {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9375rem;
  color: var(--gray-700);
  font-family: 'DM Sans', sans-serif;
}
.egift-feature::before { content: '✓'; color: var(--green); font-weight: 700; }
.egift-visual {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 32px;
  box-shadow: var(--shadow-md);
  text-align: center;
}
.egift-visual h3 { font-size: 1.25rem; color: var(--forest); margin-bottom: 16px; }
.egift-actions { display: flex; flex-direction: column; gap: 12px; }
.egift-action-link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 20px;
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  color: var(--gray-700);
  font-family: 'DM Sans', sans-serif;
  transition: all var(--transition);
}
.egift-action-link:hover { border-color: var(--green); color: var(--green); background: var(--green-light); }
.egift-action-icon { font-size: 1.25rem; }

/* ── Gift FAQ ── */
.faq-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-md);
  padding: 24px;
}
.faq-item h4 { font-size: 1rem; color: var(--forest); margin-bottom: 10px; }
.faq-item p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; font-family: 'DM Sans', sans-serif; }

/* ── Store Locator ── */
.locator-hero {
  background: var(--cream-light);
  padding: 40px 0;
  border-bottom: 1px solid var(--gray-100);
}
.locator-hero h1 { font-size: 2.25rem; color: var(--forest); margin-bottom: 8px; }
.locator-hero p { font-size: 1rem; color: var(--gray-500); font-family: 'DM Sans', sans-serif; }
.locator-controls {
  display: flex;
  gap: 12px;
  margin-top: 24px;
  flex-wrap: wrap;
  align-items: center;
}
.order-type-toggle {
  display: flex;
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  overflow: hidden;
}
.order-type-btn {
  padding: 10px 24px;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-500);
  transition: all var(--transition);
  border-radius: var(--radius-full);
}
.order-type-btn.active { background: var(--green); color: var(--white); }
.locator-search {
  display: flex;
  align-items: center;
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  padding: 4px 4px 4px 20px;
  gap: 8px;
  min-width: 320px;
  flex: 1;
  max-width: 480px;
}
.locator-search:focus-within { border-color: var(--green); }
.locator-search input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 0.9375rem;
  font-family: 'DM Sans', sans-serif;
  background: transparent;
}
.locator-search-btn {
  padding: 8px 20px;
  background: var(--green);
  color: var(--white);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  transition: background var(--transition);
}
.locator-search-btn:hover { background: var(--green-dark); }
.filter-btn {
  padding: 10px 20px;
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-700);
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all var(--transition);
}
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn.active { background: var(--green-light); border-color: var(--green); color: var(--green); }

.locator-main { display: grid; grid-template-columns: 380px 1fr; min-height: 600px; }
.results-panel { overflow-y: auto; border-right: 1px solid var(--gray-100); max-height: 680px; }
.results-header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.results-header h3 { font-family: 'DM Sans', sans-serif; font-size: 1rem; font-weight: 600; color: var(--gray-700); }
.results-count { font-size: 0.8125rem; color: var(--gray-400); }
.store-result {
  padding: 20px 24px;
  border-bottom: 1px solid var(--gray-100);
  cursor: pointer;
  transition: background var(--transition);
}
.store-result:hover { background: var(--green-light); }
.store-result.selected { background: var(--green-light); border-left: 3px solid var(--green); }
.store-name { font-size: 1rem; font-weight: 600; color: var(--gray-900); margin-bottom: 4px; }
.store-address { font-size: 0.875rem; color: var(--gray-500); margin-bottom: 8px; font-family: 'DM Sans', sans-serif; }
.store-meta { display: flex; gap: 12px; font-size: 0.8125rem; color: var(--gray-400); font-family: 'DM Sans', sans-serif; flex-wrap: wrap; }
.store-tag {
  padding: 2px 10px;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--gray-600);
}
.store-tag.open { background: var(--green-light); color: var(--green-dark); }
.map-container {
  position: relative;
  background: linear-gradient(145deg, #e8f0e8 0%, #d4e8d4 100%);
  min-height: 680px;
  overflow: hidden;
}
.map-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  color: var(--gray-500);
}
.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  background: var(--green);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  cursor: pointer;
  transition: transform var(--transition);
  box-shadow: var(--shadow-md);
}
.map-pin::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 12px;
  height: 12px;
  background: white;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}
.map-pin:hover { transform: rotate(-45deg) scale(1.2); }
.map-pin.selected { background: var(--forest); }

/* ── Filter Panel ── */
.filter-panel {
  display: none;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-top: 12px;
  box-shadow: var(--shadow-md);
}
.filter-panel.open { display: block; }
.filter-panel h4 { font-size: 0.9375rem; font-weight: 700; color: var(--gray-700); margin-bottom: 12px; }
.filter-options { display: flex; flex-wrap: wrap; gap: 10px; }
.filter-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  cursor: pointer;
  transition: all var(--transition);
  font-family: 'DM Sans', sans-serif;
}
.filter-checkbox input { display: none; }
.filter-checkbox:has(input:checked) { border-color: var(--green); background: var(--green-light); color: var(--green-dark); font-weight: 600; }

/* ── Search Suggestions ── */
.search-suggestions {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: none;
  z-index: 50;
  max-width: 480px;
}
.search-suggestions.open { display: block; }
.suggestion-item {
  padding: 12px 20px;
  font-size: 0.9375rem;
  color: var(--gray-700);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: background var(--transition);
  font-family: 'DM Sans', sans-serif;
}
.suggestion-item:hover { background: var(--green-light); color: var(--green); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image { display: none; }
  .seasonal-inner { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: repeat(3, 1fr); }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: relative; top: auto; max-height: none; }
  .tiers-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; }
  .locator-main { grid-template-columns: 1fr; }
  .results-panel { max-height: 360px; }
  .egift-inner { grid-template-columns: 1fr; }
  .business-inner { flex-direction: column; }
  .gift-hero-inner { flex-direction: column; }
}
@media (max-width: 768px) {
  .nav-links, .nav-actions { display: none; }
  .nav-mobile-toggle { display: block; }
  .hero-content h1 { font-size: 2rem; }
  .promo-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr; }
  .footer-col h4 { cursor: pointer; display: flex; align-items: center; justify-content: space-between; }
  .footer-col h4::after { content: '+'; font-size: 1.25rem; font-weight: 400; transition: transform var(--transition); }
  .footer-col.open h4::after { transform: rotate(45deg); }
  .footer-col ul { display: none; }
  .footer-col.open ul { display: flex; }
  .footer-accordion-toggle { display: block; }
  .steps-grid { grid-template-columns: 1fr; }
  .partnerships-grid { grid-template-columns: 1fr; }
  .app-inner { flex-direction: column; text-align: center; }
  .app-buttons { justify-content: center; }
  .app-phones { justify-content: center; }
  .nondairy-inner { flex-direction: column; text-align: center; }
  .faq-grid { grid-template-columns: 1fr; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 16px; font-size: 0.875rem; }
  .redemption-content { padding: 32px 24px; }
  .locator-controls { flex-direction: column; align-items: stretch; }
  .locator-search { max-width: none; min-width: unset; }
  .carousel-btn-prev { left: 4px; }
  .carousel-btn-next { right: 4px; }
  .footer-bottom { flex-direction: column; text-align: center; gap: 12px; }
}
@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .section { padding: 48px 0; }
  .hero { min-height: 400px; }
  .btn-lg { padding: 14px 28px; font-size: 1rem; }
  .redemption-tabs { gap: 4px; }
  .menu-items-grid { grid-template-columns: repeat(2, 1fr); }
}
