.seasonal-panel h2 { font-size: 1.75rem; color: var(--forest); }
.seasonal-panel p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.7; font-family: 'DM Sans', sans-serif; }

/* ── Nondairy Banner ── */
