/* ── Section Headers ── */
.section-header { text-align: center; margin-bottom: 48px; }
.section-header h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); color: var(--forest); margin-bottom: 12px; }
.section-header p { font-size: 1.0625rem; color: var(--gray-500); max-width: 560px; margin: 0 auto; font-family: 'DM Sans', sans-serif; }
.section-eyebrow {
  display: inline-block;
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
