.breadcrumb a:hover { color: var(--green); }
.breadcrumb span { color: var(--gray-700); font-weight: 500; }

/* ── Menu Page ── */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  padding: 40px 0 80px;
}
.menu-sidebar {
