.menu-item-info h4 { font-family: 'DM Sans', sans-serif; font-size: 0.9375rem; font-weight: 600; color: var(--gray-900); margin-bottom: 4px; }
.menu-item-info p { font-size: 0.8125rem; color: var(--gray-400); }

/* ── Rewards Page ── */
.rewards-hero {
