.tier-name { font-size: 1.25rem; font-family: 'DM Serif Display', serif; }
.tier-threshold { font-size: 0.8125rem; color: var(--gray-400); margin-top: 2px; font-family: 'DM Sans', sans-serif; }
.tier-benefits { display: flex; flex-direction: column; gap: 10px; }
.tier-benefit {
  display: flex;
