.partner-info p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; font-family: 'DM Sans', sans-serif; }

/* ── App Download ── */
.app-section { background: var(--forest); color: var(--white); }
.app-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
.app-text h2 { font-size: 2rem; color: var(--cream); margin-bottom: 12px; }
