/* ── Gift Cards ── */
.gift-hero { background: linear-gradient(135deg, #FFF8F0, #FCEBD0); padding: 64px 0; }
.gift-hero-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
