.gift-hero p { font-size: 1rem; color: var(--gray-500); max-width: 440px; margin-bottom: 28px; font-family: 'DM Sans', sans-serif; }
.gift-hero-cards { display: flex; gap: 12px; }
.gift-card-mini {
  width: 100px;
