}
.carousel-btn:hover { border-color: var(--green); color: var(--green); box-shadow: var(--shadow-md); }
.carousel-btn-prev { left: -22px; }
.carousel-btn-next { right: -22px; }

.gift-card-item {
  flex: 0 0 220px;
  cursor: pointer;
