  padding: 64px 0;
}
.business-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; }
.business-text h2 { font-size: 2rem; color: var(--cream); margin-bottom: 12px; }
.business-text p { font-size: 1rem; color: rgba(255,255,255,0.8); max-width: 500px; margin-bottom: 24px; font-family: 'DM Sans', sans-serif; }
.business-badge {
  display: flex;
