.egift-section { background: var(--cream-light); }
.egift-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.egift-text h2 { font-size: 1.75rem; color: var(--forest); margin-bottom: 16px; }
.egift-text p { font-size: 0.9375rem; color: var(--gray-500); line-height: 1.7; margin-bottom: 20px; font-family: 'DM Sans', sans-serif; }
.egift-features { display: flex; flex-direction: column; gap: 12px; }
.egift-feature {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9375rem;
  color: var(--gray-700);
