.faq-item p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; font-family: 'DM Sans', sans-serif; }

/* ── Store Locator ── */
.locator-hero {
  background: var(--cream-light);
  padding: 40px 0;
  border-bottom: 1px solid var(--gray-100);
}
.locator-hero h1 { font-size: 2.25rem; color: var(--forest); margin-bottom: 8px; }
