  color: var(--white);
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  transition: background var(--transition);
}
.locator-search-btn:hover { background: var(--green-dark); }
.filter-btn {
  padding: 10px 20px;
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-700);
