}
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn.active { background: var(--green-light); border-color: var(--green); color: var(--green); }

.locator-main { display: grid; grid-template-columns: 380px 1fr; min-height: 600px; }
.results-panel { overflow-y: auto; border-right: 1px solid var(--gray-100); max-height: 680px; }
.results-header {
