.store-result.selected { background: var(--green-light); border-left: 3px solid var(--green); }
.store-name { font-size: 1rem; font-weight: 600; color: var(--gray-900); margin-bottom: 4px; }
.store-address { font-size: 0.875rem; color: var(--gray-500); margin-bottom: 8px; font-family: 'DM Sans', sans-serif; }
.store-meta { display: flex; gap: 12px; font-size: 0.8125rem; color: var(--gray-400); font-family: 'DM Sans', sans-serif; flex-wrap: wrap; }
