.filter-checkbox:has(input:checked) { border-color: var(--green); background: var(--green-light); color: var(--green-dark); font-weight: 600; }

/* ── Search Suggestions ── */
.search-suggestions {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: none;
  z-index: 50;
  max-width: 480px;
}
.search-suggestions.open { display: block; }
.suggestion-item {
  padding: 12px 20px;
  font-size: 0.9375rem;
  color: var(--gray-700);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: background var(--transition);
  font-family: 'DM Sans', sans-serif;
}
.suggestion-item:hover { background: var(--green-light); color: var(--green); }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-image { display: none; }
  .seasonal-inner { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: repeat(3, 1fr); }
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: relative; top: auto; max-height: none; }
  .tiers-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; }
  .locator-main { grid-template-columns: 1fr; }
  .results-panel { max-height: 360px; }
  .egift-inner { grid-template-columns: 1fr; }
  .business-inner { flex-direction: column; }
  .gift-hero-inner { flex-direction: column; }
}
@media (max-width: 768px) {
  .nav-links, .nav-actions { display: none; }
  .nav-mobile-toggle { display: block; }
  .hero-content h1 { font-size: 2rem; }
  .promo-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr; }
  .footer-col h4 { cursor: pointer; display: flex; align-items: center; justify-content: space-between; }
  .footer-col h4::after { content: '+'; font-size: 1.25rem; font-weight: 400; transition: transform var(--transition); }
  .footer-col.open h4::after { transform: rotate(45deg); }
  .footer-col ul { display: none; }
  .footer-col.open ul { display: flex; }
  .footer-accordion-toggle { display: block; }
  .steps-grid { grid-template-columns: 1fr; }
  .partnerships-grid { grid-template-columns: 1fr; }
  .app-inner { flex-direction: column; text-align: center; }
  .app-buttons { justify-content: center; }
  .app-phones { justify-content: center; }
  .nondairy-inner { flex-direction: column; text-align: center; }
  .faq-grid { grid-template-columns: 1fr; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 16px; font-size: 0.875rem; }
  .redemption-content { padding: 32px 24px; }
  .locator-controls { flex-direction: column; align-items: stretch; }
  .locator-search { max-width: none; min-width: unset; }
  .carousel-btn-prev { left: 4px; }
  .carousel-btn-next { right: 4px; }
  .footer-bottom { flex-direction: column; text-align: center; gap: 12px; }
}
@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .section { padding: 48px 0; }
  .hero { min-height: 400px; }
  .btn-lg { padding: 14px 28px; font-size: 1rem; }
  .redemption-tabs { gap: 4px; }
  .menu-items-grid { grid-template-columns: repeat(2, 1fr); }
}
